#!/usr/bin/env python3
"""Numerical illustrations for generated exponential-logarithmic numbers.

The computations demonstrate expression evaluation and bounded searches for
small polynomial residuals. They do not claim to prove transcendence or
algebraic independence: any such proof must quantify over infinitely many
polynomials.
"""

from __future__ import annotations

import argparse
from dataclasses import dataclass
from itertools import product
import math
from typing import Iterator, Sequence


@dataclass(frozen=True)
class Expr:
    """A finite expression generated by 1, +, *, exp, and log."""

    op: str
    left: "Expr | None" = None
    right: "Expr | None" = None

    def evaluate(self) -> float:
        """Evaluate the expression recursively using IEEE-754 floats."""
        if self.op == "one":
            return 1.0
        if self.left is None:
            raise ValueError(f"operation {self.op!r} requires an operand")
        a = self.left.evaluate()
        if self.op == "exp":
            return math.exp(a)
        if self.op == "log":
            if a <= 0.0:
                raise ValueError("this numerical demo evaluates log only on positive inputs")
            return math.log(a)
        if self.right is None:
            raise ValueError(f"operation {self.op!r} requires two operands")
        b = self.right.evaluate()
        if self.op == "add":
            return a + b
        if self.op == "mul":
            return a * b
        raise ValueError(f"unknown operation: {self.op!r}")

    def render(self) -> str:
        """Return a readable mathematical representation."""
        if self.op == "one":
            return "1"
        if self.left is None:
            raise ValueError("malformed expression")
        if self.op in {"exp", "log"}:
            return f"{self.op}({self.left.render()})"
        if self.right is None:
            raise ValueError("malformed expression")
        symbol = "+" if self.op == "add" else "*"
        return f"({self.left.render()} {symbol} {self.right.render()})"


def concrete_expression() -> Expr:
    """Build exp(exp(1)) + log(1 + 1) as a finite expression tree."""
    one = Expr("one")
    return Expr(
        "add",
        Expr("exp", Expr("exp", one)),
        Expr("log", Expr("add", one, one)),
    )


def horner(coefficients: Sequence[int], x: float) -> float:
    """Evaluate a polynomial with ascending coefficients by Horner's rule."""
    value = 0.0
    for coefficient in reversed(coefficients):
        value = value * x + coefficient
    return value


def bounded_polynomials(degree: int, height: int) -> Iterator[tuple[int, ...]]:
    """Yield nonzero integer coefficient tuples of degree at most ``degree``."""
    if degree < 0 or height < 1:
        raise ValueError("degree must be nonnegative and height must be positive")
    for coefficients in product(range(-height, height + 1), repeat=degree + 1):
        if any(coefficients):
            yield coefficients


def smallest_residuals(
    x: float, degree: int, height: int, count: int = 8
) -> list[tuple[float, tuple[int, ...]]]:
    """Find the smallest |p(x)| in a finite bounded polynomial search."""
    candidates = [
        (abs(horner(coefficients, x)), coefficients)
        for coefficients in bounded_polynomials(degree, height)
    ]
    candidates.sort(key=lambda item: item[0])
    return candidates[:count]


def format_polynomial(coefficients: Sequence[int]) -> str:
    """Format ascending integer coefficients as a polynomial in T."""
    terms: list[str] = []
    for power, coefficient in enumerate(coefficients):
        if coefficient == 0:
            continue
        monomial = "" if power == 0 else ("T" if power == 1 else f"T^{power}")
        magnitude = abs(coefficient)
        body = monomial if monomial and magnitude == 1 else f"{magnitude}{monomial}"
        if not terms:
            terms.append(("-" if coefficient < 0 else "") + body)
        else:
            terms.append((" - " if coefficient < 0 else " + ") + body)
    return "".join(terms) or "0"


def run_demo(degree: int, height: int) -> None:
    """Print the concrete evaluation and a clearly delimited finite search."""
    expression = concrete_expression()
    exp_exp_one = math.exp(math.exp(1.0))
    log_two = math.log(2.0)
    value = expression.evaluate()

    print("Generated exponential-logarithmic expression")
    print("--------------------------------------------")
    print(f"Expression : {expression.render()}")
    print(f"exp(exp(1)): {exp_exp_one:.15f}")
    print(f"log(2)     : {log_two:.15f}")
    print(f"sum        : {value:.15f}")
    print(f"direct check error: {abs(value - (exp_exp_one + log_two)):.3e}")
    print()
    print(f"Finite polynomial search: degree <= {degree}, coefficient height <= {height}")
    print("This is numerical exploration, not a transcendence test.")
    for residual, coefficients in smallest_residuals(value, degree, height):
        print(f"  |p(sum)| = {residual:.6e}   p(T) = {format_polynomial(coefficients)}")


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--degree", type=int, default=3, help="maximum polynomial degree")
    parser.add_argument("--height", type=int, default=4, help="coefficient absolute bound")
    return parser.parse_args()


if __name__ == "__main__":
    arguments = parse_args()
    run_demo(arguments.degree, arguments.height)
